/// An in-progress database transaction or savepoint.
///
/// A transaction is a sequence of operations performed as a single logical unit
/// of work. All commands within a transaction are guaranteed to execute on the
/// same database connection.
///
/// A transaction is started by calling [`crate::Pool::begin`] or
/// [`Connection::begin`]. Top-level transactions use
/// [`TransactionBehavior::Immediate`] unless a different default or
/// [`Self::begin_with`] is set. It must be concluded by calling
/// either [`commit()`] or [`rollback()`], both of which consume the
/// transaction.
///
/// If a `Transaction` object is dropped without being explicitly committed or
/// rolled back, it will automatically be rolled back.
///
/// ### Savepoints (Nested Transactions)
///
/// A `Transaction` can also represent a savepoint within a larger transaction.
/// Calling `begin()` on an existing `Transaction` will create a new savepoint.
///
/// [`commit()`]: Self::commit()
/// [`rollback()`]: Self::rollback()
#[derive(Debug)]
pub struct Transaction<C = PoolConnection>
where
    C: DerefMut<Target = Connection> + Send, {/* private fields */}

impl<C> Transaction<C>
where
    C: DerefMut<Target = Connection> + Send,
{
    /// Begin a transaction using the connection's default behavior.
    pub async fn begin(conn: C) -> crate::Result<Self>;

    /// Begin a transaction with an explicit start mode.
    ///
    /// Nested calls still create savepoints. `behavior` applies only when this
    /// is the outer transaction.
    pub async fn begin_with(conn: C, behavior: TransactionBehavior) -> crate::Result<Self>;

    /// Commits this transaction or savepoint.
    pub async fn commit(self) -> crate::Result<()>;

    /// Aborts this transaction or savepoint.
    pub async fn rollback(self) -> crate::Result<()>;
}

impl<C> Deref for Transaction<C>
where
    C: DerefMut<Target = Connection> + Send,
{
    type Target = Connection;
}

impl<C> DerefMut for Transaction<C> where C: DerefMut<Target = Connection> + Send {}

impl<C> Drop for Transaction<C> where C: DerefMut<Target = Connection> + Send {}

impl<C> crate::query::as_connection::AsConnection for Transaction<C> where
    C: DerefMut<Target = Connection> + Send
{
}

impl<C> crate::query::as_connection::Sealed for Transaction<C> where
    C: DerefMut<Target = Connection> + Send
{
}

/// How SQLite starts a top-level transaction.
///
/// Nested [`Transaction::begin`] calls still create savepoints.
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
pub enum TransactionBehavior {
    /// `BEGIN DEFERRED`. Locks are taken when they are needed.
    Deferred,
    /// `BEGIN IMMEDIATE`. A reserved lock is taken at begin.
    ///
    /// This is the default. Most explicit transactions write, and Immediate
    /// avoids `SQLITE_BUSY_SNAPSHOT` when a second connection commits between
    /// a deferred read and a later write.
    #[default]
    Immediate,
    /// `BEGIN EXCLUSIVE`. An exclusive lock is taken at begin.
    Exclusive,
}

/// SQLite transaction lock state reported by [`sqlite3_txn_state`].
///
/// This is the actual connection state. It does not report savepoint
/// nesting. [`Connection::is_autocommit`] reports whether an explicit
/// transaction is open.
///
/// [`sqlite3_txn_state`]: https://www.sqlite.org/c3ref/txn_state.html
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum TxnState {
    /// No transaction is active (`SQLITE_TXN_NONE`).
    None,
    /// A read transaction is active (`SQLITE_TXN_READ`).
    Read,
    /// A write transaction is active (`SQLITE_TXN_WRITE`).
    Write,
}

/// One row change delivered by [`crate::Connection::on_update`].
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct UpdateEvent {
    /// Insert, update, or delete.
    pub op: UpdateOp,
    /// Database name, usually `main`.
    pub database: String,
    /// Table name.
    pub table: String,
    /// Rowid of the changed row.
    pub rowid: i64,
}

/// Row-change operation reported by `sqlite3_update_hook`.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum UpdateOp {
    /// `INSERT`.
    Insert,
    /// `UPDATE`.
    Update,
    /// `DELETE`.
    Delete,
}

/// Owned representation of a SQLite value.
///
/// Each variant stores the underlying value along with an optional
/// [`SqliteDataType`] describing how SQLite declared the column.
/// When the type information is omitted the variant's natural type is used.
///
/// The variants closely mirror SQLite's dynamic typing system and allow a
/// single enum to capture every value that can be transferred between the
/// database and user code.
///
/// **Note:** This enum is marked `#[non_exhaustive]`; do not match on it
/// exhaustively as more variants may be added in the future.
#[derive(Clone, Debug)]
#[non_exhaustive]
pub enum Value {
    /// A NULL value. If the original column declared a specific type the
    /// information is stored in `type_info` for use during decoding.
    Null {
        /// Original declared type, if known.
        type_info: Option<SqliteDataType>,
    },
    /// A 64-bit signed integer.
    Integer {
        /// The raw integer value.
        value: i64,
        /// Original declared type, if known.
        type_info: Option<SqliteDataType>,
    },
    /// A double precision floating point number.
    Double {
        /// The raw floating point value.
        value: f64,
        /// Original declared type, if known.
        type_info: Option<SqliteDataType>,
    },
    /// A UTF-8 text value.
    Text {
        /// Validated UTF-8 text.
        value: Text,
        /// Original declared type, if known.
        type_info: Option<SqliteDataType>,
    },
    /// An arbitrary blob of bytes.
    Blob {
        /// Blob bytes.
        value: Bytes,
        /// Original declared type, if known.
        type_info: Option<SqliteDataType>,
    },
}

impl Value {
    /// Returns the raw bytes contained in [`Value::Blob`] or [`Value::Text`].
    ///
    /// For other variants an empty slice is returned.
    pub fn blob(&self) -> Result<&[u8], DecodeError>;

    /// Returns the value as `f64` if it is numeric.
    ///
    /// Integer values are automatically widened to `f64`. Any other variant
    /// results in a [`DecodeError::Conversion`].
    pub fn double(&self) -> Result<f64, DecodeError>;

    /// Returns the value as `i32` if it is an integer and fits in the range.
    pub fn int(&self) -> Result<i32, DecodeError>;

    /// Returns the value as `i64` if it is stored as an integer.
    ///
    /// Fails with [`DecodeError::Conversion`] if the value is not an integer.
    pub fn int64(&self) -> Result<i64, DecodeError>;

    /// Returns `true` if the value is [`Value::Null`].
    pub fn is_null(&self) -> bool;

    /// Interprets the value as UTF‑8 encoded text and returns it.
    ///
    /// Returns an error if the value is not [`Value::Text`].
    pub fn text(&self) -> Result<&str, DecodeError>;

    /// Returns the [`SqliteDataType`] associated with this value.
    ///
    /// If no explicit type information was captured when the value was read,
    /// the variant's natural type is returned instead.
    pub fn type_info(&self) -> SqliteDataType;
}

impl<'r> Decode<'r> for Value {}

/// An ordered collection of key-value pairs for building dynamic SQL queries.
///
/// When used with the `sql!` macro's `{where:values}` placeholder, `NULL`
/// values are rendered as `col IS NULL` (without a bound parameter).
///
/// Values may also include SQL expression fragments (see [`crate::expr`]) for
/// computed columns in `{set:...}` and `{insert:...}` placeholders.
#[derive(Clone, Debug, Default)]
pub struct Values(_);

impl Values {
    /// Extends this collection with the key-value pairs from another `Values`
    /// collection.
    ///
    /// If a key exists in both collections, the value from `other` will
    /// overwrite the existing value in this collection. The insertion order
    /// is preserved, with existing keys maintaining their position and new
    /// keys appended.
    pub fn extend(&mut self, other: &Self);

    /// Inserts a key-value pair into the collection.
    /// The key should be the name of the database column.
    pub fn insert<K, V>(&mut self, key: K, value: V) -> crate::Result<()>
    where
        K: Into<String>,
        V: IntoValuesEntry;

    /// Returns `true` if the collection contains no elements.
    pub fn is_empty(&self) -> bool;

    /// Iterate over key-value pairs in insertion order.
    pub fn iter(&self) -> impl Iterator<Item = (&String, &ValuesEntry)>;

    /// Iterate over the keys in insertion order.
    pub fn keys(&self) -> impl Iterator<Item = &String>;

    /// Returns the number of elements in the collection.
    pub fn len(&self) -> usize;

    /// Creates a new, empty `Values` collection.
    pub fn new() -> Self;

    /// Consumes `self`, inserts a key-value pair, and returns `Self` for
    /// chaining.
    pub fn val<K, V>(self, key: K, value: V) -> crate::Result<Self>
    where
        K: Into<String>,
        V: IntoValuesEntry;

    /// Iterate over the values in insertion order.
    pub fn values(&self) -> impl Iterator<Item = &ValuesEntry>;
}

/// A value in a [`Values`] collection.
#[derive(Clone, Debug)]
pub enum ValuesEntry {
    /// A bound value (encoded immediately).
    Value(Value),
    /// A SQL expression fragment (may include its own bound parameters).
    Expr(Expr),
}

/// A packed bit vector stored as a BLOB.
///
/// sqlite-vec requires an explicit SQL wrapper to set the subtype for bit
/// vectors. Use `vec_bit(?)` around bound parameters.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct VecBit(pub Vec<u8>);

impl<'r> Decode<'r> for VecBit {}

impl Encode for VecBit {}

impl<T> IntoValuesEntry for VecBit where T: Encode {}

/// A `float32` vector stored as a BLOB.
///
/// This binds directly as raw bytes and works with sqlite-vec APIs that accept
/// float vectors (the default subtype).
#[derive(Clone, Debug, PartialEq)]
pub struct VecF32(pub Vec<f32>);

impl<'r> Decode<'r> for VecF32 {}

impl Encode for VecF32 {}

impl<T> IntoValuesEntry for VecF32 where T: Encode {}

/// An `int8` vector stored as a BLOB.
///
/// sqlite-vec requires an explicit SQL wrapper to set the subtype for int8
/// vectors. Use `vec_int8(?)` around bound parameters.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct VecInt8(pub Vec<i8>);

impl<'r> Decode<'r> for VecInt8 {}

impl Encode for VecInt8 {}

